CREATE POLICY "Maintenance media type and size" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (bucket_id <> 'maintenance-media' OR (name ~ '^backgrounds/[a-zA-Z0-9_.-]+$' AND ((lower(metadata->>'mimetype') = 'video/mp4' AND name ~ '\.mp4$' AND (metadata->>'size')::bigint <= 50000000) OR (lower(metadata->>'mimetype') IN ('image/jpeg','image/png','image/webp') AND name ~ '\.(jpg|png|webp)$' AND (metadata->>'size')::bigint <= 5000000))));
CREATE POLICY "Maintenance media update validation" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (bucket_id <> 'maintenance-media' OR public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id <> 'maintenance-media' OR (name ~ '^backgrounds/[a-zA-Z0-9_.-]+$' AND ((lower(metadata->>'mimetype') = 'video/mp4' AND name ~ '\.mp4$' AND (metadata->>'size')::bigint <= 50000000) OR (lower(metadata->>'mimetype') IN ('image/jpeg','image/png','image/webp') AND name ~ '\.(jpg|png|webp)$' AND (metadata->>'size')::bigint <= 5000000))));